static const char *port_tr_col(const char *k, int col) {  // colonna 1..12 (PORT_LANGS[col - 1]); chiave sconosciuta = la chiave
    for (size_t r = 0; r < sizeof(PORT_TR) / sizeof(*PORT_TR); r++) if (!strcmp(PORT_TR[r][0], k)) return PORT_TR[r][col];
    return k;
}
static const char *port_tr(const char *k) {  // la lingua corrente, altrimenti l'inglese; chiave sconosciuta = la chiave
    int col = 1;
    for (int i = 0; i < 12; i++) if (!strcmp(Lang_getLangCode(), PORT_LANGS[i])) col = i + 1;
    for (size_t r = 0; r < sizeof(PORT_TR) / sizeof(*PORT_TR); r++) if (!strcmp(PORT_TR[r][0], k)) return PORT_TR[r][col];
    return k;
}
